    "summary": "고체산화물 전해질 기반, 고온 수증기의 전기 분해를 통한 수소 생산 시스템(고온수전해(SOEC)시스템)의 효율성·안전성 검증",
    "regulation": "수소경제 육성 및 수소 안전관리에 관한 법률 제36조, 제44조, 제48조\n수소경제 육성 및 수소 안전관리에 관한 법률 시행규칙 제2조, 제22조, 제39조\n수전해설비 제조의 시설·기술·검사 기준(KGS AH271)",
    "conditions": "ㅇ SOEC를 활용한 수소 생산 시스템의 안전 확보를 위해 사업자가 안전성 평가를 실시하고, 실증안전기준 및 자체 안전관리계획을 마련한 후 이를 적용하여 수소법에 따른 인허가·검사 등 관리체계를 준수하는 조건*으로 SOEC 제조 실증을 허용\n*다만, 실증제품이 연구·개발 목적에 한정되는 것으로서 일반 국민의 피해 우려가 적은 장소에서 실시하고, 실증 후 사용·유통되지 않는 것이 보장되는 경우 수소법에 따른 인허가·검사 등 관리체계 적용 예외를 허용하며, 이 경우 사업자는 자체검사를 추가로 이행할 것\nㅇ (안전성 평가*) 사업 운영의 위험 요인 발굴 및 관리(해소) 방안 도출\n*고압가스 안전관리법 제13조의2 제1항 및 통합고시 제2절에 따른 안전성 평가 준용\nㅇ (실증안전기준) 유사 안전기준인 KGS AH271을 준용하되 고온·고전력 운전 환경과 수소품질 성능 및 수소정제장치 기준 미준수에 따른 위험 요인을 고려하고, 안전성 평가를 통해 도출된 위험 요인에 대한 안전관리 방안을 포함하여 실증안전기준을 마련·준수\nㅇ (안전관리계획*) 안전성 평가를 통해 도출된 위험 요인 관리 방안을 포함하여 실증사업의 안전 확보를 위한 안전관리계획을 수립·준수\n*수소법 제41조에 따른 안전관리규정을 준용\nㅇ (자체검사*) 사업자는 실증제품을 사용하기 전에 실증안전기준의 충족 여부를 자체적으로 검사하고 안전위원회로부터 그 검사 결과에 대한 적정 여부를 확인받을 것\n*자체검사는 수소법에 따른 인허가·검사 등 관리체계의 적용을 예외로 하는 경우에만 적용\nㅇ (안전위원회 구성·운영) 사업자는 산·학·연 전문가가 참여하는 자체안전위원회를 구성하고, 이를 통해 실증사업의 안전성을 검증\n- 위원회의 실증 전ㆍ후 검증내용ㆍ결과를 가스안전공사에 보고ㆍ승인 요청\n< 안전위원회의 주요 안전성 검증 내용 >ㆍ(실증 前) 안전성 평가 결과, 실증안전기준 및 안전관리계획의 적정 여부 등 검토ㆍ(실증 中) 실증안전기준 및 안전관리계획의 준수 여부 확인 등 주기적 모니터링ㆍ(실증 後) 실증결과 및 실증결과를 반영한 안전기준(안)의 적정성 검토\nㅇ (타법준수) 실증사업에 활용하는 수전해설비의 구성품(열교환기 등) 또는 실증시설 등이 다른 법령*에 따라 인허가, 검사, 인증 등을 받아야 하는 경우 해당 법령을 준수\n*고압가스안전관리법, 산업안전보건법, 연구실 안전환경 조성에 관한 법률 등\nㅇ (자료제공 협조) 실증과 연계한 제도화 추진을 위해 사업자는 해당 실증사업을 통해 도출한 고체산화물형 수전해설비(SOEC)의 안전 성능, 에너지 효율 등에 대한 결과를 한국가스안전공사에 공유 협조",
