    "type": "실증특례",
    "company": "한국조선해양기자재연구원",
    "title": "액화수소 활용 선박 기자재 및 인수 기지 기자재 실증설비 구축",
    "approvedDate": "2026-05-26",
    "summary": "액화수소 운반선·추진선에 적용되는 극저온 기자재와 인수기지에 탑재되는 기자재의 성능·안전성 검증을 위한 설비 실증",
    "regulation": "액화수소 기자재 시험시설 내 액화수소 저장 및 사용에 대한 시설·기술 기준이 없어 검사 불가(고압가스 안전관리법)",
    "conditions": "조건1\nㅇ (현행 관리체계) 사업자는 임시 실증안전기준 및 안전관리방안 등을 포함하는 안전관리계획을 마련하고 이를 이행, 안전관리위원회가 검증 및 모니터링, 검사기관이 검사하는 안전관리체계 구축\n\n   ① (사업자) 가스안전공사가 제시하는 액화수소 관련「가스안전공사 실증안전기준」을 반영한 자체 안전관리계획 수립‧이행\n\n   ② (안전위원회) 사업자는 산‧학‧연 전문가로 구성된 자체 안전위원회를 구성하고, 이를 통해 안전성 검증*\n      * 자체 안전관리계획의 적정성 및 이행여부 등 확인\n\n   ③ (검사기관) 액화수소 제조소 등 실증을 위해 구축되는 액화수소 시설 및 제품에 대한 검사 실시\n조건2\nㅇ (안전관리계획) 사업자는 안전성평가 등을 실시하고 그 결과를 반영하여 시설과 제품 설계 및 자체 안전관리계획 수립 및 준수\n조건3\nㅇ (안전위원회 구성·운영) 사업자는 산‧학‧연 전문가가 참여하는 자체 안전위원회를 구성하고, 이를 통해 실증사업의 안전성 검증\n조건4\nㅇ (허가 및 검사) 사업자는 액화수소 실증 시설·제품에 대해 ｢고압가스 안전관리법｣ 에 따른 인허가 및 검사 등을 받아야 함\n\n   ① (시설) 기술검토, 사업허가, 시설검사, 안전관리자 선임, 사업개시 신고 등\n\n   ② (제품) 국내외 제품 제조시설의 제조등록, 제품검사 등\n     - 저장탱크, 기화기, 안전밸브, 긴급차단장치 등\n조건5\nㅇ (타법준수) 액화수소 실증사업에 활용되는 액화수소 시설 및 제품 등이 다른 법령*에 따라 인허가, 검사, 인증 등을 받아야 하는 경우 해당 법령을 준수\n조건6\nㅇ (자료제공 협조) 실증과 연계한 제도화 추진을 위해 사업자는 해당 실증사업을 통해 도출한 액화수소 시설 및 제품의 실증결과를 한국가스안전공사에 제출",
