    "summary": "기체수소 기반시설(연료전지, 저장용기 등)을 지하에 구축 및 운영하여 관련 기술의 안전성 검증",
    "regulation": "고압가스 안전관리법 시행규칙 제8조, 별표4, 별표5\n고압가스 일반제조의 시설·기술·검사·감리·안전성평가 기준(KGS FP112)\n수소경제 육성 및 수소 안전관리에 관한 법률 시행규칙 제44조, 제47조, 별표5\n수소연료사용시설의 시설·기술·검사 기준(KGS FU671)",
    "conditions": "ㅇ 지하에 설치하는 설비 등 시설의 안전 확보를 위해 사업자가 안전성 평가를 실시하고, 실증안전기준 및 자체 안전관리계획을 마련한 후 이를 적용하여 고법에 따른 인허가·검사 등 관리체계를 준수하는 조건으로 수소발전시설의 지하 설치에 관한 실증 허용*\n* 2주 간 실증 진행 후, 관련 시설 철거하는 조건\nㅇ (안전성 평가*) 사업 운영의 위험 요인 발굴 및 관리(해소) 방안 도출\n* 고법 제13조의2제1항 및 통합고시 제2절에 따른 안전성 평가 준용\nㅇ (실증안전기준) 유사 안전기준인 KGS FP112를 준용하되, 안전성 평가 결과 및 가연성 가스의 취급 환경, 공정 등을 고려한 실증안전기준을 마련하고, 이를 적용하여 고법 체계* 준수\n* 고법 제4조(고압가스 제조허가 등), 제16조(검사 등) 등\nㅇ (안전관리계획*) 안전성 평가를 통해 도출된 위험 요인 관리 방안을 포함하여 실증사업의 안전 확보를 위한 안전관리계획을 수립·준수\n* 고법 제11조에 따른 안전관리규정 준용\nㅇ (안전위원회 구성·운영) 사업자는 산·학·연 전문가가 참여하는 자체안전위원회를 구성하고, 이를 통해 실증사업의 안전성을 검증\n- 위원회의 실증 전ㆍ후 검증내용ㆍ결과를 가스안전공사에 제출ㆍ승인 요청\n< 안전성 검증 내용 >ㆍ(실증 前) 안전성 평가 결과, 실증안전기준 및 안전관리계획의 적정 여부 등 검토ㆍ(실증 中) 실증안전기준 및 안전관리계획의 준수 여부 확인 등 주기적 모니터링ㆍ(실증 後) 실증결과 및 실증결과를 반영한 안전기준(안)의 적정성 검토\n※ 사업자는 자체 안전관리계획의 적정성에 대하여 가스안전공사의 검토를 거쳐 기후부의 승인을 받아야 함\nㅇ (타법준수) 실증사업에 활용하는 가스 제품(연료전지 등) 또는 실증시설 등이 다른 법령에 따라 인허가, 검사, 인증 등을 받아야 하는 경우 해당 법령 준수\nㅇ (자료제공 협조) 실증과 연계한 제도화 추진을 위해 사업자는 해당 실증사업을 통해 도출한 가스설비실 지하 설치의 안전성 및 효율 등의 실증 결과를 한국가스안전공사에 공유 협조",
