    "conditions": "□ (안전성평가) 사업 운영의 위험 요인 발굴 및 관리(해소) 방안 도출\n□ (실증안전기준) 유사 안전기준인 KGS AH171(수소추출설비의 시설·기술·검사기준)을 준용하되 안전성 평가 결과와 플라즈마 공정과 고체 탄소 분리·회수 공정의 특성 등을 고려한 실증안전기준을 마련하고, 이를 적용하여 수소법의 관리체계를 준수\n□ (안전관리계획) 사업자는 안전성평가 등을 실시하고 그 결과를 반영하여 시설과 제품 설계 및 자체 안전관리계획 수립 및 준수\n□(자체검사) 사업자는 실증제품을 사용하기 전에 실증안전기준의 충족 여부를 자체적으로 검사하고 안전위원회로부터 그 검사 결과에 대한 적정 여부를 확인받을 것\n□ (안전위원회 구성·운영) 사업자는 산·학·연 전문가가 참여하는 자체 안전위원회를 구성하고, 이를 통해 실증사업의 안전성을 검증\n□ (타법준수) 실증사업에 활용하는 플라즈마 활용 열분해 수소추출설비의 구성품(압력용기 등) 또는 실증시설 등이 다른 법령에 따라 인허가, 검사, 인증 등을 받아야 하는 경우 해당 법령을 준수\n□ (자료제공 협조) 실증과 연계한 제도화 추진을 위해 사업자는 해당 실증사업을 통해 도출한 수소추출설비의 안전 성능 및 효율 등의 실증결과를 한국가스안전공사에 공유 협조\n※ 상세조건은 붙임 참조",
