    "conditions": "ㅇ (종합) 실증사업에 대한 안전성 확보를 전제로 실증특례 인정\n⇨ (특례 부여내용) 기존 철도와의 거리 대신 저장설비‧처리설비‧압축가스설비 및 충전설비의 외면에서 철도 ‘본선’까지 5m 이상의 거리를 유지하는 형태로 수소연료 충전시설 구축을 허용 ※ 현재 「고압가스 안전관리법 시행규칙」 별표 5 개정 추진 중\nㅇ (안전관리계획) 사업자는 자체 안전성 평가를 실시하고, 그 결과를 반영하여 시설 설계, 자체 안전관리계획 수립 및 준수\n- (안전성 평가) 사업자는 수소연료충전시설 운영에 따른 위험요인 사전 발굴 및 관리방안 마련을 위해 자체 안전성 평가* 실시\n* 고압가스 안전관리법 제13조의2 제1항 및 통합고시 제2절에 따른 안전성 평가 준용\n- (안전관리계획) 사업자는 자체 안전성 평가 결과에 따라 시설 설계, 자체 안전관리계획* 수립 및 준수\n* 자체 안전관리계획에는 추가안전기준(안) 및 안전관리계획서를 포함하고, 안전관리계획서는 고압가스법 제11조에 따른 사업자 안전관리규정을 준용\nㅇ (안전위원회 구성·운영) 사업자는 산·학·연 전문가가 참여하는 자체 안전위원회를 구성하고, 이를 통해 실증사업의 안전성 검증\n< 안전위원회의 주요 안전성 검증 내용 >ㆍ(실증 前) 안전성평가, 실증기준, 안전관리계획의 적정 여부 등 검토ㆍ(실증 中) 실증기준, 안전관리계획 준수 여부 확인 등 주기적 모니터링ㆍ(실증 後) 실증결과 및 실증결과를 반영한 안전기준(안)의 적정성 검토 *사업자는 자체 안전관리계획의 적정성에 대하여 가스안전공사의 검토를 거쳐 산업부기후부의 승인을 받아야 함\nㅇ(타법준수) 동 실증사업 추진 과정에서 다른 법령에 따라 인허가, 검사, 인증 등을 받아야 하는 경우 해당 법령을 준수\nㅇ(자료제공 협조) 실증과 연계한 제도화 추진을 위해 사업자는 해당 실증사업을 통해 도출한 실증 결과를 한국가스안전공사에 제출",
