    "company": "한국석유관리원",
    "title": "수소튜브트레일러를 이용한 수소 유통 활성화 사업",
    "approvedDate": "2025-09-25",
    "summary": "이동식 수소 튜브트레일러를 임대 지원하여 대량 공동구매 방식을 통해 수소 생산지에서 충전소로 수소 유통 * 수소법에 따른 수소유통전담기관(한국석유관리원)은 수소 공동구매 낙찰 공급업체(수소 생산 및 유통)에게 수소튜브트레일러 임대 지원 ** 수소의 수급 불안정 해소 등 현안대응 및 문제예방을 위해 산업통상자원부가 승인하는 경우, 공동구매에 참여하지 않은 업체라도 T/T 임대 지원",
    "regulation": "ㅇ 화물자동차 운수사업법 제56조 및 동법 시행규칙 제49조",
    "conditions": "□ 수소 공동구매 낙찰 공급업체에 대해서만 수소 튜브트레일러(T/T)를 임대하여 실증사업을 위해서만 사용 필요\nㅇ 다만, 수소의 수급 불안정 해소 등 공적 기능을 위해 T/T 지원이 필요하다고 산업통상자원부가 승인하는 경우, 공동구매에 참여하지 않은 업체라도 예외적으로 지원 가능\nㅇ 본 사업은 저렴한 가격으로 안정적으로 수소를 공급하기 위한 것으로, 수소경제 활성화에 기여할 수 있는 사업으로 사료됨\n- 그러나, 현재 사업구조로는 화물자동차법 위반사항이 있으므로 사업방식 개선, 법령 개정 등을 통해 원활한 사업 추진 필요\nㅇ 예를 들어, 수소법 제34조에 따른 수소유통전담기관인 한국석유관리원에서 화물운송업 허가를 득하여 직접 수소를 유통하거나,\n* 자가용 유상운송 금지의 예외사항인 영농조합법인의 경우에도 화물차를 직접 소유·운영하는 경우로 한정하고 있어 자가용 유상운송 예외를 검토하더라도 석유관리원이 직접 운영 필요\n- 한정된 유통망 내에서만 본 사업이 활용될 수 있도록 협동조합 등을 설립하는 방안 등의 검토가 필요\n- 또한, 수소법 개정을 통해 화물자동차법상 자가용 유상운송 금지 조항 적용을 배제하는 방안도 검토 가능\n* 4개 협동조합의 경우 해당 사업에 대해 개별법에서 자가용 유상운송 금지 적용을 배제 중 ☞ ｢농업협동조합법｣, ｢산림조합법｣, ｢소비자생활협동조합법｣, ｢수산업협동조합법｣\n※ 산업부 수소경제정책과는 실증특례 이후 규제개선 방안에 대해 관계부처 간 협의를 거쳐 농업협동조합법 입법례와 같이 화물자동차운수사업법 제56조의 적용 예외 근거를 수소법에 마련할 예정",
