    "approvedDate": "2025-09-25",
    "summary": "ㅇ액화수소 신뢰성 평가센터* 내 시험용 액화수소 공급·회수/재액화 시스템, 액화수소 기자재 신뢰성 평가‧실험 장비 구축 - 액화수소 수소 저장ㆍ운송 등에 활용되는 소재ㆍ부품ㆍ장비 등 설비의 신뢰성 평가 시스템 실증을 통해 성능 및 안전성 검증",
    "regulation": "ㅇ 고압가스 안전관리법 제4조, 제16조 및 제22조의2에 따른 [KGS FP112]\nㅇ 고압가스 안전관리법 제5조, 제5조의2, 제17조 및 제22조의2에 따른 [KGS AC111], [KGS AA317], [KGS AA319], [KGS AA911]",
    "conditions": "□사업자가 다음의 부대조건을 모두 포함하여 실증사업의 안전성을 확보하는 것을 전제로 다음과 같이 규제특례(실증특례)를 인정\n⇨ (특례 부여내용) 사업자는 안전성 평가를 실시하고, 실증안전기준 및 자체 안전관리계획을 마련 후 이를 적용하여 고압가스법에 따른 인허가·검사 등의 관리체계를 준수하는 등 안전 확보를 조건으로 액화수소 공급·회수·재액화 시스템 및 신뢰성 평가·실험 장비 실증을 허용\nㅇ(관리체계) 사업자는 임시 실증안전기준 및 안전관리방안 등을 포함하는 안전관리계획을 마련하고 이를 이행, 안전관리위원회가 검증 및 모니터링, 검사기관이 검사하는 안전관리체계 구축\n①(사업자) 가스안전공사가 제시하는 액화수소 관련「가스안전공사 실증안전기준」을 반영한 자체 안전관리계획을 수립‧이행\n②(안전위원회) 사업자는 산‧학‧연 전문가로 구성된 자체 안전위원회를 구성하고, 이를 통해 안전성 검증*\n*사업자의 자체 안전관리계획의 적정성 및 이행여부 등 확인\n③ (검사기관) 액화수소 실증시설 및 제품에 대한 검사 실시\n< 액화수소 실증사업 안전관리 절차 >\n그림입니다. 원본 그림의 이름: CLP000010680001.bmp 원본 그림의 크기: 가로 812pixel, 세로 131pixel\nㅇ(안전관리계획) 사업자는 안전성평가* 등을 실시하고 그 결과를 반영하여 시설과 제품 설계 및 자체 안전관리계획** 수립 및 준수\n*고압가스 안전관리법 제13조의2 제1항 및 통합고시 제2절에 따른 안전성 평가 준용\n**사업자는 자체 안전관리계획에 ‘가스안전공사 실증안전기준’ 및 이를 이행하기 위한 안전관리방안을 포함 ( ‘사업자 실증안전기준’ 추가 가능)\n※ 안전관리방안은 고압가스 안전관리법 제11조에 따른 사업자 안전관리규정 준용\nㅇ(안전위원회 구성·운영) 사업자는 산‧학‧연 전문가가 참여하는 자체 안전위원회를 구성하고, 이를 통해 실증사업의 안전성을 검증\n< 안전성 검증 내용 >ㆍ(실증 前) 안전성 평가 결과 및 안전관리계획(안) 적정 여부 등 검토ㆍ(실증 中) 안전관리계획 준수 여부 확인 등 주기적 모니터링ㆍ(실증 後) 실증결과 및 실증결과를 반영한 안전기준(안) 검토\n※사업자는 자체 안전관리계획의 적정성에 대하여 가스안전공사의 검토를 거쳐 산업부의 승인을 받아야 함\nㅇ(허가 및 검사) 사업자는 액화수소 실증 시설·제품에 대해 ｢고압가스 안전관리법｣ 에 따른 인허가 및 검사* 등을 받아야 함\n* (시설) 기술검토, 사업허가, 시설검사, 안전관리자 선임, 사업개시 신고 등(제품) 국내·외 제품 제조시설의 제조등록, 제품검사 등\nㅇ(타법준수) 액화수소 실증사업에 활용되는 액화수소 시설 및 제품 등이 다른 법령*에 따라 인허가, 검사, 인증 등을 받아야 하는 경우 해당 법령 준수\n*수소법, 산업안전보건법, 연구실 안전환경 조성에 관한 법률 등\nㅇ(자료제공 협조) 실증과 연계한 제도화 추진을 위해 사업자는 해당 실증사업을 통해 도출한 액화수소 시설 및 제품의 실증결과를 한국가스안전공사에 제출",
