    "summary": "수소연료전지 기반의 하이브리드 에너지원 시스템을 사용하는 다목적 무인잠수정의 효율 및 에너지원 안전성 검증",
    "regulation": "ㅇ 본 실증 무인잠수정에 탑재되는 수소연료전지는 수소법에 따라 수소용품에 해당하나 관련 안전기준 및 인허가·검사 기준 부재\nㅇ 본 실증에 사용할 용기는 441리터 복합재료용기(12개~15개)로 운송용 용기에 해당되어 잠수정(모빌리티)에 설치 및 사용 불가\nㅇ 본 실증에 사용되는 무인잠수정은 고압가스 저장허가(수소, 산소, 질소) 대상이나 저장설비가 수중상태를 유지해야 하는 잠수정 운용특성상 고압가스 저장시설의 허가 취득 불가",
    "conditions": "□ KGS AC419에 따라 제조하여 검사에 합격한 복합재료용기를 무인잠수정의 연료공급용으로 사용하는 것을 허용\n□ 무인잠수정에 설치되는 수소, 산소 및 질소 저장설비는 고압가스 안전관리법 제4조제5항에 따른 허가 및 같은 법 제20조에 따른 특정고압가스 사용신고의 예외를 허용\n□ (안전성 평가) 사업 운영의 위험 요인 발굴 및 관리(해소) 방안 도출\n□ (실증안전기준) 기본 안전기준으로는 KGS AH372를 준용하되 해상 운전 환경의 취급 특성을 고려하고, 안전성 평가를 통해 도출된 위험 요인에 대한 안전관리방안을 포함하여 실증안전기준을 마련·준수\n□ (안전관리계획) 안전성 평가를 통해 도출된 위험 요인 관리 방안을 포함하여 실증사업의 안전 확보를 위한 안전관리계획을 수립·준수\n□ (자체검사) 사업자는 실증제품을 사용하기 전에 실증안전기준의 충족 여부를 자체적으로 검사하고 안전위원회로부터 그 검사 결과에 대한 적정 여부를 확인받을 것\n□ (안전위원회 구성·운영) 사업자는 산·학·연 전문가가 참여하는 자체 안전위원회를 구성하고, 이를 통해 실증사업의 안전성을 검증\n□(타법준수) 실증사업에 활용하는 이동형 연료전지의 구성품(압력용기 등) 또는 실증시설 등이 다른 법령에 따라 인허가, 검사, 인증 등을 받아야 하는 경우 해당 법령을 준수\n□ (자료제공 협조) 실증과 연계한 제도화 추진을 위해 사업자는 해당 실증사업을 통해 도출한 이동형 연료전지의 안전 성능 및 효율 등의 실증결과를 한국가스안전공사에 공유 협조\n□ 실증사업을 종료한 후, 실증에 사용된 용기를 폐기하고 이를 객관적으로 증명할 수 있는 서류(폐기 전·후 사진대지 포함 등)를 작성하여 KGS로 제출\n□ 해상 실증 과정의 안전관리계획을 수립하고 한국가스안전공사로부터 검토를 받은 후 이를 준수\n※ 상세조건은 붙임 참조",
