    "conditions": "□ (실증기준) 사업자는 ➊현행 「고압가스 안전관리법」의 안전관리 체계에 따라 제조등록을 하여야 하고, ➋대용량 복합재료 용기(Type-4)에 대한 안전성을 확보할 수 있도록 가스안전공사와 협의하여 실증기준(안) 마련 필요\n< ➊ 용기의 제조등록 면제: 불수용 >\nㅇ (현행 법령준수) 압축수소 운송용 대용량 복합재료용기는 제조등록을 포함하여「고압가스 안전관리법」에 따른 안전관리 체계 준수 필요\n< ➋ 압축수소 운송용 대용량(1,600리터급) 복합재용기 제조: 조건부 수용 >\nㅇ (실증기준) 대용량 복합재료용기(Type-4)는 국제표준(ISO11515*)에 따라 제조하며,「고압가스 안전관리법」에 따른 안전관리 체계(용기 신규검사 등) 준수\nㅇ (일일점검) 대용량 복합재료용기(Type-4) 및 튜브트레일러 일일점검 실시\nㅇ (재검사) 대용량 운송용 복합재료용기에 대에 대해「고압가스 안전관리법」에 따라 용기의 재검사 기준 등 안전관리 방안 마련·준수 필요\n< 공통사항 >\nㅇ(안전관리계획) 안전성 평가를 통해 도출된 위험 요인의 관리 방안을 포함하여 실증사업의 안전 확보를 위한 안전관리계획을 수립·준수\nㅇ(안전위원회 구성·운영) 사업자는 산·학·연 전문가가 참여하는 자체 안전위원회를 구성하고, 이를 통해 실증사업의 안전성 검증\nㅇ (타법준수) 실증사업에 활용되는 대용량(1,600리터급) 복합재료용기를 포함한 실증설비 및 시설 등이 다른 법령에 따라 인허가, 검사, 인증 등을 받아야 하는 경우 해당 법령을 준수\nㅇ (자료제공 협조) 실증과 연계한 제도화 추진을 위해 사업자는 해당 실증사업을 통해 도출한 실증 결과를 한국가스안전공사에 공유 협조\n※ 상세조건은 붙임 참조",
