    "regulation": "❶ KGS AC419에 따라 제조된 복합재료 용기는 그 사용 용도가 운송용으로 제한\n「고압가스안전관리법」(AC419) 압축수소 운송용 비금속라이너 복합재료용기 제조 기준\n❷ 선박용 연료전지는 검사 기준이 없어 제조·사용이 제한\n「수소경제 육성 및 수소 안전관리에 관한 법률」 제36조, 제44조\n「수소경제 육성 및 수소 안전관리에 관한 법률 시행규칙」제36조, 제43조, 제44조, 제48조\n❸ 무인잠수정에 설치되는 수소 용기 등 저장설비는 고압가스 안전관리법에 따른 저장소 설치 허가 및 특정고압가스 사용신고 대상\n「고압가스 안전관리법」 제3조제1호, 제4조제5항, 제20조제1항\n「고압가스 안전관리법 시행규칙」 제2조제2항, 제46조제1항",
