    "conditions": "ㅇ (안전성 평가) 사업 운영의 위험 요인 발굴 및 관리(해소) 방안 도출\nㅇ (실증안전기준) KGS FU671을 준용하되 해상 구조물 내에서 가연성가스 설비 운영 등을 고려하여 실증안전기준을 마련하고, 이를 적용하여 수소법의 관리체계를 준수\nㅇ (안전관리계획) 안전성 평가를 통해 도출된 위험 요인 관리 방안을 포함하여 실증사업의 안전 확보를 위한 안전관리계획을 수립·준수\nㅇ (안전위원회 구성·운영) 사업자는 산·학·연 전문가가 참여하는 자체 안전위원회를 구성하고, 이를 통해 실증사업의 안전성을 검증\nㅇ (타법준수) 실증시설 등이 다른 법령에 따라 인허가, 검사, 인증 등을 받아야 하는 경우 해당 법령 준수\nㅇ (자료제공 협조) 실증과 연계한 제도화 추진을 위해 사업자는 해당 실증사업을 통해 도출한 결과를 한국가스안전공사에 공유 협조",
