    "regulation": "① 액화수소 저장‧배관에 의한 수소 판매시설 구축에 필요한 시설‧기술‧검사기준 부재\n고압가스 안전관리법 제4조 제1항, 고압가스 안전관리법 시행규칙 제8조 제1항 제4호 [별표 8], 고압가스 안전관리법 제22조의2 제1항 제1호에 따른 [KGS FU111]\n② 액화수소 저장‧배관에 의한 수소 판매시설에 설치되는 주요 설비(저장탱크 등)의 시설·기술·검사기준 부재\n고압가스 안전관리법 제3조 제3호, 제5호, 제 5조 제1항, 제2항, 제17조 제1항, 고압가스 안전관리법 시행규칙 제9조 [별표 12], 고압가스 안전관리법 제22조의2 제1항 제2호에 따른 [KGS AC111], [KGS AA911], [KGS AA319], [KGS AA317]",
