    "title": "고체산화물 수전해기(SOEC)를 포함한 수소 생산 실험실 및 설비 시스템",
    "approvedDate": "2024-07-18",
    "summary": "이온을 제거한 물로 스팀을 생산 후 고체산화물 수전해기(SOEC)*에 주입하여 수소 생산 실증** * 고체산화물 수전해기(SOEC: Solid Oxide Electrolysis Cell) : 고체산화물 전해질을 사용하여 물 분자를 수소와 산소로 분해하는 장치 ** 국내ㆍ외 고체산화물 수전해기 제조사가 제조한 다수의 설비(스택)를 성능 평가 실증 모듈에 변경·설치, 반복평가함으로써 운전성능 등을 확인할 예정",
    "regulation": "ㅇ 수소경제 육성 및 수소 안전관리에 관한 법률 제36조, 제44조\nㅇ 수소경제 육성 및 수소 안전관리에 관한 법률 시행규칙 제39조\nㅇ 수전해설비 제조의 시설·기술·검사 기준 “KGS AH271”\n- 고체산화물 수전해기(SOEC)는 제조에 관한 시설·기술·검사기준 부재, 수소 정제장치 없이 스택으로만 구성되는 고체산화물 수전해기(SOEC)의 성능 평가 모듈에 대한 기하학적 범위 정의 부재, 스택 성능 평가 위한 스택 변경 시 마다 수소용품 검사 재실시 의무",
    "conditions": "➊실험실 설계(10㎾급 SOEC 스택 성능평가) 관련\n⇨ (특례 부여내용) 실증 사업자가 스택의 성능평가와 관련한 안전성 평가를 실시하고, 그 결과를 반영하여 자체 안전관리계획을 수립·준수하는 조건으로 실험실 설계(스택 성능평가)에 대해서는 수소법에 따른 인허가·검사 등 관리체계의 적용 예외를 허용\nㅇ(안전성 평가*) 사업 운영의 위험 요인 발굴 및 관리(해소) 방안 도출\n*고압가스 안전관리법 제13조의2 제1항 및 통합고시 제2절에 따른 안전성 평가 준용\nㅇ(안전관리계획*) 안전성 평가를 통해 도출된 위험 요인 관리 방안을 포함하여 실증사업의 안전 확보를 위한 안전관리계획을 수립·준수\n*고압가스 안전관리법 제11조 및 수소법 제41조에 따른 안전관리규정 준용\n➋시스템 설계(160㎾ SOEC 시스템) 관련\n⇨ (특례 부여내용) 실증 사업자가 SOEC의 안전 확보와 관련 안전성 평가를 실시하고, 실증안전기준 및 자체 안전관리계획을 마련한 후 이를 적용하여 수소법에 따른 인허가·검사 등 관리체계를 준수하는 조건*으로 SOEC 제조에 관한 실증을 허용 *다만, 실증제품이 연구·개발 목적에 한정되는 것으로서 국민의 피해 우려가 적은 장소에서 실시하고, 실증 후 사용·유통되지 않는 것이 보장되는 경우 수소법에 따른 인허가·검사 등 관리체계 적용 예외를 허용하며, 이 경우 사업자는 다음에 따른 자체검사를 할 것\nㅇ(안전성 평가*) 사업 운영의 위험 요인 발굴 및 관리(해소) 방안 도출\n*고압가스 안전관리법 제13조의2 제1항 및 통합고시 제2절에 따른 안전성 평가 준용\nㅇ(실증안전기준) 유사 안전기준인 KGS AH271을 준용하되, 고온·고전력 운전 환경 및 안전성 평가를 통해 도출된 위험 요인에 대한 안전관리 방안을 포함하여 실증안전기준을 마련·준수\nㅇ(안전관리계획*) 안전성 평가를 통해 도출된 위험 요인 관리 방안을 포함하여 실증사업의 안전 확보를 위한 안전관리계획을 수립·준수\n*고압가스 안전관리법 제11조 및 수소법 제41조에 따른 안전관리규정 준용\nㅇ(자체검사*) 사업자는 실증제품을 사용하기 전에 실증안전기준의 충족 여부를 자체적으로 검사하고 안전위원회로부터 그 검사 결과에 대한 적정 여부를 확인받을 것\n*자체검사는 수소법에 따른 인허가·검사 등 관리체계의 적용을 예외로 하는 경우에만 적용함\n➌공통 사항\nㅇ(안전위원회 구성·운영) 사업자는 산·학·연 전문가가 참여하는 자체 안전위원회를 구성하고, 이를 통해 실증사업의 안전성을 검증\n< 안전성 검증 내용 >ㆍ(실증 前) 안전성평가, 실증기준, 안전관리계획 및 자체검사 결과의 적정 여부 등 검토ㆍ(실증 中) 실증기준, 안전관리계획 준수 여부 확인 등 주기적 모니터링ㆍ(실증 後) 실증결과 및 실증결과를 반영한 안전기준(안)의 적정성 검토\n*위원회의 실증 전·중·후 검증내용 및 결과를 가스안전공사에 보고·승인 요청\nㅇ(타법준수) 실증사업에 활용하는 성능평가장비 및 수전해설비와 그 구성품(열교환기 등) 또는 실증시설 등이 다른 법령*에 따라 인허가, 검사, 인증 등을 받아야 하는 경우 해당 법령을 준수\n*고압가스 안전관리법, 산업안전보건법, 연구실 안전환경 조성에 관한 법률 등\nㅇ(자료제공 협조) 실증과 연계한 제도화 추진을 위해 사업자는 해당 실증사업을 통해 도출한 고체산화물형 수전해설비(SOEC)의 안전 성능, 에너지 효율 등에 대한 결과를 한국가스안전공사에 공유 협조",
    "sourceUrl": "https://sandbox.kiat.or.kr/front/pstmng/selectCtlExeLibPage.do",
