    "regulation": "① 액화수소 사용시설에 대한 시설·기술·검사 기준 부재\n고압가스 안전관리법 제20조 제1항, 제3항, 제4항\n고압가스 안전관리법 시행규칙 제46조 제1항 제1호, 제47조 및 제48조 제5항에 따른 [별표 8]\n고압가스 안전관리법 제22조의2 제1항 제11호에 따른 [KGS FU211]\n② 액화수소 저장탱크 및 설비 제조에 대한 시설·기술·검사 기준 부재\n고압가스 안전관리법 제5조 제1항, 제2항, 제17조 제1항\n고압가스 안전관리법 시행규칙 제9조 및 제43조[별표 12]\n고압가스 안전관리법 제22조의2 제1항 제2호 및 제10호에 따른 [KGS AC111], [KGS AA317]",
    "conditions": "ㅇ (관리체계) 사업자는 자체 안전관리계획을 마련‧이행하고 안전위원회가 검증‧모니터링, 검사기관이 검사하는 안전관리 체계 구축\nㅇ (안전관리계획) 사업자는 안전성 평가를 실시하고 그 결과를 반영하여 시설과 제품 설계 및 자체 안전관리계획 수립 및 준수\nㅇ (안전성 검증) 사업자는 안전성 확보를 위해 실증 단계별로 안전관리계획의 적정성 및 이행 여부 등을 확인하고, 그 결과를 안전관리위원회·가스안전공사 검토를 거쳐 산업부 승인을 받아야 함\nㅇ (신고 및 검사) 액화수소 사용시설 및 제품에 대해 ｢고압가스 안전관리법｣ 검사체계에 따른 사용신고 및 검사 등을 받아야 함",
