    "approvedDate": "2024-05-09",
    "summary": "비금속 배관 및 피팅을 사용한 AEM 수전해 모듈 활용 수소생산설비",
    "regulation": "ㅇ 수소경제 육성 및 수소 안전관리에 관한 법률 제36조(수소용품 제조사업 허가) 제1~4항, 동법 제44조(수소용품의 수입 및 검사) 제1, 4항\nㅇ 동법 시행규칙 제22조(수소용품 제조사업 등의 허가 및 등록 절차 등) 제1, 3항\nㅇ 수전해설비 제조의 시설·기술·검사 기준(KGS AH271) 1.1.1, 3.1.1.1~3.1.1.2\n  - 수전해설비는「수소경제 육성 및 수소 안전관리에 관한 법률」에 따른 수소용품으로, 제조자는 인허가, 제품검사 등 수소법상 규정 준수 필요 => 현행법상 수전해 설비 제조 시 수용액이 통하는 배관은 금속 재료를 사용해야 함 → 신청기업은 수용액이 흐르는 배관 및 피팅을 비금속 재료로 사용해 시설·기술·검사 기준에 부적합",
    "conditions": "ㅇ 수전해설비의 제조자는「수소법」에 따른 수소용품 제조허가(제36조), 수소용품 검사(제44조) 등 안전관리체계를 준수\nㅇ 고압가스법 등 다른 법령에 따라 인허가, 검사·인증을 받아야 하는 경우 등 해당 법령 준수\nㅇ 사업자는 KOH 수용액의 누출 등 실증사업의 위험 요인을 사전에 발굴 및 관리하기 위해 자체 안정성 평가를 실시하고, 그 결과를 반영하여 실증안전기준을 포함하는 안전관리계획 수립·준수\nㅇ 사업자는 산·학·연 전문가가 참여하는 자체 안전위원회를 구성하고, 이를 통해 실증사업의 안전성을 검증\nㅇ 사업자는 본 실증사업에 활용한 비금속 재료에 대하여 내화학성 및 내식성에 관한 공인시험기관의 시험성적서와 실증 운전 후 기밀성능의 변화 등에 관한 자료를 한국가스안전공사에 공유 협조",
