    "summary": "수소 운송용 Type4 용기를 컨테이너 트레일러에 장착하여 수소 출하센터와 수소   충전소 간 수소 운송 및 공급 실증",
    "regulation": "ㅇ ( 수소용기) 수소 운송용 용기는 고압가스법에 따라 제조등록 및 검사를 받아야 하나, 현재 국내의 Type4 용기에 대한 기준이 본 실증 제품과 맞지 않아 사업화 제한\n- (제조등록) 실증에 대한 Type4 용기에 대한 제조등록 기준 면제 요청\n- (용기검사) 운송용 용기검사 기준인 KGS AC419*는 450리터 이하, 사용압력 450Bar 이하 기준을 적용하나 본 실증 제품은 2,000리터급에 사용압력 517Bar 규격 제품으로 검사기준이 일치하지 않아 사업화 제한",
    "conditions": "ㅇ 복합재료 용기(Type4)는 국제기준(ISO 11515)의 기준에 따라 제조하고, 「고압가스 안전관리법」의 관리체계를 준수\nㅇ 용기의 설계단계검사 및 생산단계검사 기준은 ISO 11515 준용하고, 미 교통부(DOT) 또는 유럽(TPED)에 따라 인증받은 용기를 사용\nㅇ (안전관리계획) 사업자는 자체 안전성 평가를 실시하고 그 결과를 반영하여 실증안전기준을 마련한 후, 자체 안전관리계획을 수립·준수\nㅇ (안전성 검증) 사업자는 산·학·연 전문가가 참여하는 자체 안전위원회를 구성하고, 이를 통해 실증사업의 안전성을 검증",
