    "conditions": "□ (관리체계) 사업자는 실증안전기준 등 안전관리계획을 마련·이행하고 안전위원회가 검증·모니터링, 검사기관이 검사하는 안전관리 체계 구축\n□ (안전관리계획) 사업자는 안전성평가 등을 실시하고 그 결과를 반영하여 시설과 제품 설계 및 자체 안전관리계획 수립 및 준수\n□ (안전성 검증) 사업자는 안전성 확보를 위해 실증 단계별로 안전관리계획의 적정성 및 계획 이행 여부 등을 확인하고, 그 결과를 자체 안전위원회 및 가스안전공사 검토를 거쳐 산업부의 승인 필요\n□ (허가 및 검사) 액화수소 충전시설 및 제품에 대해 고압가스 안전관리법 검사체계에 따른 인허가 및 검사 등 필요\n※ 상세조건은 붙임 참조",
