    "summary": "ㅇ 고농도(99.5%이상) 액체 상태의 무수 암모니아를 직접 전기분해 할 수 있는 수소추출기 제작 및 실증을 통한 안전성 검증 ☞ 기존 유사 기술대비 75~80% 정도 에너지효율이 높아 그로 인해 수소 생산단가를 획기적으로 낮출 수 있는 방식에 대한 실증 추진",
    "regulation": "수소경제 육성 및 수소 안전관리에 관한 법률 제2조, 제36조, 제44조 및 동 시행규칙 제2조, 제22조, 제26조, 제39조, 고압가스 안전관리법 제17조 및 동 시행령 제 2조",
    "conditions": "<산업통상자원부 에너지안전과>\n□ 사업자는 무수 액화암모니아 전기분해 수소추출설비의 운전 특성 등을 고려 실증안전기준*을 마련하고, 이를 적용하여 인허가·검사 등 「수소법」의 안전관리체계**를 준수\n* 유사 기준인 수전해설비 제조 안전기준(KGS AH271)을 준용하되 독성·가연성가스 취급에 따른 기기의 작동 특성과 안전성평가를 통해 도출된 위험 요인 등을 고려하여 마련 要\n** 법 제36조(수소용품 제조사업 허가), 제38조(외국수소용품의 제조등록), 제44조(제품검사) 등\n□ 사업자는 스택의 파열시험을 대체하여 설계적정성(강도)의 검증을 위한 구조응력해석(Analysis) 등의 방안*과 다음의 주요 사항 및 안전성 평가를 통해 도출된 위험 요인을 고려하여 실증안전기준을 마련·준수하는 조건으로 스택을 “압력용기”가 아닌 「수소법」에 따른 수소추출설비의 부품으로서 안전관리를 허용\n* 유한요소 응력해석 또는 다른 응력해석 프로그램과 스택 전체가 아닌 단위 셀의 파열시험 적용 등을 포함하며, 사업자가 제시한 검증 방법의 적정 여부는 압력용기 등 관련 전문가의 사전 검토 필요\nㅇ(안전장치) 사업자는 스택의 최고사용압력을 초과하지 않도록 과압안전장치를 설치하고, 과압 발생 시 운전을 정지하는 장치 설치 필요\nㅇ(차압성능) 사업자는 스택 내 분리막을 경계로 음극과 양극 측에 다른 크기의 압력(차압) 작용시, 분리막 사이 내압성능 확보 방안 필요\n<실증사업 안전관리 체계(공통사항)>\nㅇ(안전관리계획) 사업자는 자체 안전성 평가를 실시하고 그 결과를 반영하여 무수 액화암모니아 전기분해 수소추출설비의 제작·실증에 관한 자체 안전관리계획을 수립 및 준수\n- (안전성 평가*) 사업 운영에 따른 위험요인 사전 발굴 및 관리방안 마련\n*고압가스안전관리법 제13조의2 제1항 및 통합고시 제2절에 따른 안전성 평가 준용\n- (안전관리계획) 안전성 평가 결과를 반영하여 시설·제품을 설계하고 실증안전기준을 포함하는 안전관리계획*을 수립‧준수\n*고압가스안전관리법 제11조 및 수소법 제41조에 따른 안전관리규정 준용\nㅇ(타법준수) 수소추출설비의 구성품 또는 수소생산 실증을 위해 해당 설비를 설치·운영하는 시설이 다른 법령*에 따라 인허가, 검사 등을 받아야 하는 경우 해당 법령을 준수\n*고압가스 안전관리법, 화학물질관리법, 산업안전보건법 등\nㅇ(안전성 검증) 사업자는 산·학·연 전문가(가스안전공사 필참)가 참여하는 자체 안전위원회를 구성하고, 이를 통해 실증사업의 안전성을 검증\n< 안전성 검증 내용 >ㆍ(실증 前) 구조응력해석 등 스택의 설계검증 방법 및 실증기준, 안전성평가, 안전관리계획 및 자체검사 결과의 적정 여부 등 검토 → 스택의 설계검증 방법이 불충분한 경우, 추가적인 설계해석(Analysis) 요구 가능ㆍ(실증 中) 실증기준, 안전관리계획 준수 여부 확인 등 주기적 모니터링ㆍ(실증 後) 실증결과 및 실증결과를 반영한 안전기준(안)의 적정성 검토\n*위원회의 실증 전·중·후 검증내용 및 결과를 가스안전공사에 보고·승인 요청",
    "sourceUrl": "https://sandbox.kiat.or.kr/front/pstmng/selectCtlExeLibPage.do",
