    "conditions": "□ 現 수소충전소의 자동차 충전 기준(고칙 별표 5, KGS FP217) 및 실증기준(안) 적용 조건으로 충방전 모사장치(자동차용기) 충전 허용\nㅇ 실증기준(안)\n< 수소충전소 안전성 확보 관련 >\nㅇ (충전소 구축) 신청기업은 수소충전소 구축에 대하여 인허가(변경허가* 포함), 검사 등 현행 고압가스법에 따른 안전관리체계 준수\n* 저장설비 및 처리설비(압력용기 등)의 위치 또는 능력변경 등(시행규칙 제4조)\n< 충방전 모사장치 안전성 확보 관련 >\nㅇ (충방전 모사장치) 위험성 평가결과*를 반영한 모사장치 설계·제작\n* 기 실시한 위험성 평가(‘20.12) 결과의 적정성은 안전관리위원회를 통하여 검증\nㅇ (장치 유지·관리) 모사장치의 충전 중 이탈방지, 차량충돌 보호대*설치 및 일일점검 등 유지·관리에 필요한 안전관리 방안 마련\n* 충전소 내 상용버스 운행에 따른 모사장치의 충돌 방지 조치 필요\nㅇ (용기 안전조치) 충방전 모사장치의 용기가 설계충전횟수*(약 4,000회)를 초과하지 않도록 용기충전횟수 모니터링\n* 자동차관리법 관련 고시에 따라 제조·검사하는 자동차 내압용기는 설계수명(15년 이하) 또는 설계충전횟수 제한\nㅇ (충전 안전조치) 충방전 모사장치의 용기 충전은 수소차 충전의 국제기준*(충전프로토콜)을 적용하여 안전성 확보 필요\n* 상업용(버스 등) 수소차량에 대한 충전기준 SAE J2601, JPEC-S0003 등\nㅇ (가스방출 안전조치) 모사장치의 충전수소는 충전소 과압안전정차의 가스방출관을 통해 방출시키는 등 가스방출 안전관리 방안 마련\nㅇ (안전관리계획) 사업자는 자체 안전성 평가*를 실시하고 그 결과를 반영하여 충전소 설계 및 자체 안전관리계획을 수립 및 준수\n* 변경허가 대상(저장·처리설비 교체 등) 외 실증사업 중 수행되는 충전소 설비 및 모사장치 부품 교체·변경에 대한 안전관리방안 내용 포함\nㅇ (안전성 검증) 기업은 업계ㆍ학계ㆍ유관기관(가스안전공사 필참) 등 전문가 참여 자체 안전위원회 구성 → 실증사업의 안전성 검증\n< 안전성 검증 내용 >ㆍ(실증 前) 모사장치 위험성평가결과, 안전관리계획(안) 및 실증기준(안)의 적정여부 등 검토ㆍ(실증 中) 실증기준, 안전관리계획 준수 여부 확인 등 주기적 모니터링ㆍ(실증 後) 실증결과 및 실증결과를 반영한 안전기준(안) 검토\n* 위원회의 실증 전·중·후 검증내용·결과를 가스안전공사를 거쳐 산업부로 보고·승인 요청",
