    "conditions": "1. 산업부가 제시한 조건(첨부) 및 향후 가스안전공사가 별도로 제시할 예정인 상세 실증기준 준수\n2. 액화수소 충전소 21기의 구축은 허용하나, 실제 운영 규모 및 기간은 산업부와 신청기업간 추후 협의하여 결정\n3. 충전소의 수소공급처는 창원, 인천지역 액화수소 생산에 대한 실증특례사업자에 한하여 추가가능 (단, 산업부와 사전협의 필요)",
