    "conditions": "1. 실증특례 기간: 24개월(다만, 기간 내 관련 법령 개정 시 해당 내용을 따를 것)\n2. 실증특례부여 조건\n① 연료전지 안전성 확보방안 준수(첨부1)\n② 전문위·소방청 협의내용 준수\n- (위험성 평가) 박미 주유소 위험성 평가 결과 제출일로부터 2주 내 산업부·소방청 추천 전문가와 검토하여 안전기준 확정 후 사업개시\n- (실증장소) 박미 주유소 사업개시 후 일반적 구조의 주유소를 포함한 10곳을 선정하여 소방청·산업부와 협의 후* 실증진행\n*박미 주유소 사업개시 후 일반적 구조의 주유소 2-3곳을 선정하여 동일한 방식으로 위험성 평가 진행, 나머지 7-8곳은 위험성 평가 면제",
